local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["a4027093172fbf39"] = { "Ho stabilito il contatto, {name}. È Lokholar the Ice Lord. Ha giudicato degna la nostra causa, sufficiente il nostro sacrificio legato alla terra. Arriverà presto... preparati.", "." },
  ["a40b02c0d7798d06"] = { "Più di mille anni fa, un gruppo di sacerdoti troll noti come Atal'ai tentò di riportare in vita un antico dio del sangue chiamato Hakkar the Soulflayer. Dopo la guerra civile che ne seguì, i sacerdoti furono sconfitti ed esiliati nella ⟦Swamp of Sorrows=Palude del Dolore⟧. Lì eressero un tempio a Hakkar per preparare il suo arrivo nel mondo fisico. L'Aspetto dei draghi Ysera venne presto a sapere dei piani degli Atal'ai e sprofondò il tempio sotto le paludi. Ancora oggi, le rovine del tempio sono sorvegliate dai possenti draghi verdi.", "." },
  ["a4111b4615fc274c"] = { "Voglio unirmi alla battaglia!", "." },
  ["a413a2d503bdf128"] = { "Pesciolino, pesciolino... vieni da papà.", "." },
  ["a41a94cf7c3f42d3"] = { "L'ippogrifo è una bestia nobile, fiera e veloce. Addestrarli è un onore, e portano in fretta il loro cavaliere molto lontano.", "." },
  ["a41ebe7fe4de5414"] = { "Lo so, questo cuoio blu attira l'occhio. Vedi, qui intorno abbiamo un gran numero di reclute impazienti che cacciano e uccidono con più entusiasmo che saggezza. Bisogna prendere precauzioni.", "." },
  ["a42035222430cc9f"] = { "Kyra Windblade maneggia la sua lama con grande abilità. Dovrebbe poterti dare un po' di addestramento. La trovi alla locanda di Dolanaar.", "." },
  ["a4227aca6137b0b6"] = { "Non abbiamo assolutamente bisogno di attirare altra attenzione su di noi, <straniero/straniera>. Torna da chi ti ha mandato in cerca del maestro perduto e digli che non si è trovato nulla. Quando l'avrai fatto (e io saprò quando sarà così), torna e ti rivelerò i segreti del defunto.", "." },
  ["a42329eca112b65f"] = { "Ma guarda un po'! <Un/Una> <nuovo/nuova> <allievo/allieva>! Ti insegnerò volentieri tutto quello che so, quando avrai un po' più di abilità. Intanto va' a parlare con Gretta Finespindle, laggiù, ti va? Ti metterà in pari in un attimo.", "." },
  ["a4252be3c6bcf94b"] = { "Ti sembrerà strano, ma ultimamente gli affari non vanno poi così bene...", "." },
  ["a428c1948757d823"] = { "Non lasciate niente dietro di voi!", "." },
  ["a428e3bc028abc91"] = { "<Benvenuto/Benvenuta>, <fratello/sorella> <mio/mia>. Se sei qui per addestrarti, sarò felice di insegnarti.\n\nNon fa mai male riaffermare il proprio posto in quello che mi piace chiamare il Grande Equilibrio. Come custodi di questo equilibrio, dobbiamo sforzarci di mantenere sempre la mente lucida e il cuore saldo. L'addestramento ci aiuta in questo.", "." },
  ["a4290fdf16c99e66"] = { "Ho atteso abbastanza. Ora affronterai il mietitore di anime.", "." },
  ["a434130c222f58ed"] = { "Morte a te, {name}. Come osi avvicinarti a me a tiro d'arco!", "." },
  ["a436b9b98533fd79"] = { "Voglio vedere la tua merce.", "." },
  ["a43924262498f0f1"] = { "Non sento più caldo...", "." },
  ["a43a62e6d413335e"] = { "No, non credo ci siano incantatori qui nella ⟦Elwynn Forest=Foresta di Elwynn⟧. Però c'è un tizio di nome Lucan che gestisce una bottega su a ⟦Stormwind=Roccavento⟧. Potresti chiedere a lui e vedere se ti addestra.", "." },
  ["a44412dcfa5710e2"] = { "Quante altre provviste ci servono?", "." },
  ["a455bcbc8fe523a8"] = { "Il diario di Jandice Barov è pieno di farneticazioni e deliri sui non morti. Verso la fine del libro c'è quello che sembra uno schema di sartoria per creare una Sacca di Telavile. Gli stregoni usano questa sacca per conservare i frammenti d'anima. Sai già come creare questa sacca.", "." },
  ["a45a668e88df4127"] = { "Ho quasi abbastanza provviste per passare alle unità veterane.", "." },
  ["a4626e486328dba4"] = { "Aiuto! Salvatemi!", "." },
  ["a462c1ca921ba66e"] = { "%s borbotta parole incomprensibili.", "." },
  ["a469a7d611475ede"] = { "Bene, bene, ma guarda un po', scintilla, ce l'abbiamo fatta. È tutto raccolto e pronto a partire. Aspettiamo solo quei bifolchi dell'⟦Horde=Orda⟧, e appena si danno una mossa si parte di corsa per ⟦Ahn'Qiraj=Ahn'qiraj⟧!", "." },
  ["a47990d975e978e9"] = { "La nostra causa cade nel vuoto oltre le spesse mura di pietra di ⟦Stormwind=Roccavento⟧.", "." },
  ["a47b29f63ca02f75"] = { "Quid pro quo! Ti insegnerò ciò che so, ma prima voglio che tu svolga un piccolo compito...", "." },
  ["a47bb9c64034299c"] = { "Seguimi, {name}. Presto inizierò l'evocazione...", "." },
  ["a47c8904b785b390"] = { "Su questa tavola di legno sono appesi dei rozzi avvisi di taglia.", "." },
  ["a4835d1ff85261dd"] = { "Ottimo! Continuate a portare provviste, gente!", "." },
  ["a483ad57b38c5115"] = { "Recita le tue preghiere!", "." },
  ["a48aea97bbf664da"] = { "Molto bene, Gerard. Il prossimo passo sarà allevarli.", "." },
  ["a48bcd2b37db8ce7"] = { "Sono un orco della medicina, {race}. Se sei qui per imparare, farò del mio meglio per insegnarti.", "." },
  ["a48f50df5aefdf40"] = { "%s ti sorprende a manomettere le scorte di frutta dell'accampamento e ti attacca!", "." },
  ["a4904eb18c5bd00f"] = { "Se stai cercando di fare amicizia, risparmia il fiato. Anzi, meglio ancora: smetti proprio di respirare.", "." },
  ["a493f15ebd9b35b1"] = { "C'è una sola regola che secondo me devi conoscere, se vuoi sopravvivere in questo mondo: più sai, più vedrai.\n\nSe studi, se osservi, comincerai a vedere nel mondo cose che nessun altro {race} vedrà.", "." },
  ["a49dc7ac23d7b94b"] = { "Che affari hai con me? Sono un uomo molto impegnato...", "." },
  ["a4a5680b352c5bc3"] = { "Neanche una parola....", "." },
  ["a4a7dc5fc1f51173"] = { "Mia signora, non merito la tua preghiera. Sei davvero un angelo di luce. Ti prego, aiutami a tornare alla tana dei tumuli, così che io possa tornare nel Sogno. Anch'io, come Malfurion, ho un amore che mi aspetta... devo tornare da lei... per proteggerla...", "." },
  ["a4afa885ddfb6779"] = { "Hai fatto tuoi i nostri nemici. Dividerò volentieri le acque con te.", "." },
  ["a4b2b07cded87133"] = { "Va' nella ⟦Valley of Honor=Valle dell'Onore⟧ e cerca Xon'cha vicino alle stalle.", "." },
  ["a4b96a71bec35493"] = { "%s versa l'acqua corrotta sul gatto.", "." },
  ["a4c32965a4d1f8e3"] = { "%s ride mentre guarda le bestiole scappare.", "." },
  ["a4cc040b853164ba"] = { "Noi molto più puliti di quegli ogre a Tanaris. Per tutto il deserto, a perdita d'occhio: cacca di ogre. Qui no, <signore/signora>, qui no!", "." },
  ["a4de044414909735"] = { "Lo ⟦The Scepter of the Shifting Sands=Scettro delle Sabbie Mutevoli⟧ è di nuovo integro, {name}.\n\nSei tu che devi guidare i tuoi eserciti nella maledetta città fortezza di ⟦Ahn'Qiraj=Ahn'qiraj⟧ e fare giustizia dei suoi abitanti.\n\nRecati a ⟦Silithus=Silitus⟧ e presenta lo ⟦The Scepter of the Shifting Sands=Scettro delle Sabbie Mutevoli⟧ a Jonathan the Revelator.", "." },
  ["a4dec0e4cdf4d444"] = { "Oh oh....", "." },
  ["a4e506ad724413a7"] = { "In ginocchio, Grark.", "." },
  ["a4e7c77551632cd0"] = { "Vuoi imparare a ricavare il cuoio dalle bestie uccise? O ti servono degli attrezzi nuovi?", "." },
  ["a4eacd2166595458"] = { "%s solleva in alto gli oggetti che {name} gli ha dato...", "." },
  ["a4f17e3ab1ab189a"] = { "Posso insegnarti a maneggiare il martello da fabbro, se vuoi imparare.", "." },
  ["a4f1afa5a691ea01"] = { "%s sussulta.", "." },
  ["a4f555325ea003a9"] = { "Bodley, dimmi cosa sta succedendo.", "." },
})
